
// Lista para armazenar as tarefas
let tarefas = [];

// Função para cadastrar uma tarefa
function cadastrarTarefa() {

    let codigo = document.getElementById("codigo").value.trim();
        let titulo = document.getElementById("titulo").value.trim();
            let prioridade = document.getElementById("prioridade").value;

                let mensagem = document.getElementById("mensagem");

                    // Verificar campos vazios
                        if (codigo === "" || titulo === "" || prioridade === "") {
                                mensagem.style.color = "red";
                                        mensagem.innerText = "Preencha todos os campos!";
                                                return;
                                                    }

                                                        // Validar tamanho do título
                                                            if (titulo.length < 5) {
                                                                    mensagem.style.color = "red";
                                                                            mensagem.innerText = "O título deve ter no mínimo 5 caracteres!";
                                                                                    return;
                                                                                        }

                                                                                            // Validar prioridade
                                                                                                if (![1, 2, 3].includes(Number(prioridade))) {
                                                                                                        mensagem.style.color = "red";
                                                                                                                mensagem.innerText = "Prioridade inválida!";
                                                                                                                        return;
                                                                                                                            }

                                                                                                                                // Verificar código duplicado
                                                                                                                                    if (tarefas.some(t => t.codigo === codigo)) {
                                                                                                                                            mensagem.style.color = "red";
                                                                                                                                                    mensagem.innerText = "Código já cadastrado!";
                                                                                                                                                            return;
                                                                                                                                                                }

                                                                                                                                                                    // Criar objeto da tarefa
                                                                                                                                                                        let tarefa = {
                                                                                                                                                                                codigo: codigo,
                                                                                                                                                                                        titulo: titulo,
                                                                                                                                                                                                prioridade: Number(prioridade),
                                                                                                                                                                                                        concluida: false
                                                                                                                                                                                                            };

                                                                                                                                                                                                                tarefas.push(tarefa);

                                                                                                                                                                                                                    mensagem.style.color = "green";
                                                                                                                                                                                                                        mensagem.innerText = "Tarefa cadastrada com sucesso!";

                                                                                                                                                                                                                            document.getElementById("codigo").value = "";
                                                                                                                                                                                                                                document.getElementById("titulo").value = "";
                                                                                                                                                                                                                                    document.getElementById("prioridade").value = "";

                                                                                                                                                                                                                                        listarTarefas();
                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                        // Função para listar tarefas
                                                                                                                                                                                                                                        function listarTarefas() {

                                                                                                                                                                                                                                            let lista = document.getElementById("lista");

                                                                                                                                                                                                                                                lista.innerHTML = "";

                                                                                                                                                                                                                                                    if (tarefas.length === 0) {
                                                                                                                                                                                                                                                            lista.innerHTML = "<p>Nenhuma tarefa cadastrada.</p>";
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                    tarefas.forEach((tarefa, indice) => {

                                                                                                                                                                                                                                                                            let prioridade = "";

                                                                                                                                                                                                                                                                                    if (tarefa.prioridade === 1) {
                                                                                                                                                                                                                                                                                                prioridade = "Alta";
                                                                                                                                                                                                                                                                                                        } else if (tarefa.prioridade === 2) {
                                                                                                                                                                                                                                                                                                                    prioridade = "Média";
                                                                                                                                                                                                                                                                                                                            } else {
                                                                                                                                                                                                                                                                                                                                        prioridade = "Baixa";
                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                        lista.innerHTML += `
                                                                                                                                                                                                                                                                                                                                                                    <div class="tarefa">

                                                                                                                                                                                                                                                                                                                                                                                    <h3>${tarefa.titulo}</h3>

                                                                                                                                                                                                                                                                                                                                                                                                    <p>Código: ${tarefa.codigo}</p>

                                                                                                                                                                                                                                                                                                                                                                                                                    <p>Prioridade: ${prioridade}</p>

                                                                                                                                                                                                                                                                                                                                                                                                                                    <p>Status: ${
                                                                                                                                                                                                                                                                                                                                                                                                                                                        tarefa.concluida ? "Concluída" : "Pendente"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }</p>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button onclick="concluirTarefa(${indice})">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Concluir
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button onclick="alterarPrioridade(${indice})">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Alterar prioridade
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <button onclick="excluirTarefa(${indice})">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Excluir
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </button>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        `;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                atualizarResumo();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Função para concluir tarefa
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function concluirTarefa(indice) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    tarefas[indice].concluida = true;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        alert("Tarefa concluída com sucesso!");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            listarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Função para alterar prioridade
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function alterarPrioridade(indice) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let novaPrioridade = prompt(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Digite a nova prioridade:\n1 - Alta\n2 - Média\n3 - Baixa"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (novaPrioridade === null) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    novaPrioridade = Number(novaPrioridade);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (![1, 2, 3].includes(novaPrioridade)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                alert("Digite uma prioridade válida!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                tarefas[indice].prioridade = novaPrioridade;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    alert("Prioridade alterada com sucesso!");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        listarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Função para excluir tarefa
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function excluirTarefa(indice) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let confirmar = confirm(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "Deseja realmente excluir esta tarefa?"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (confirmar) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    tarefas.splice(indice, 1);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            alert("Tarefa excluída com sucesso!");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    listarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Função para atualizar o resumo
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function atualizarResumo() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let total = tarefas.length;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let concluidas = tarefas.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        tarefa => tarefa.concluida
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ).length;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let pendentes = total - concluidas;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("total").innerText = total;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("concluidas").innerText = concluidas;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("pendentes").innerText = pendentes;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Iniciar o sistema
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            listarTarefas();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            